import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import {
  assertAbsoluteIsoTimestamp,
  nextUpdatedTimestamp,
} from "../../db/timestamps";
import { STAGE_KINDS } from "../../db/types";
import type {
  Application,
  ApplicationTimelineEvent,
  Stage,
  StageKind,
} from "../../db/types";

export interface DefaultStageDefinition {
  id: string;
  name: string;
  color: string;
  order: number;
  kind: StageKind;
}

export const DEFAULT_STAGES = [
  { id: "stage-saved", name: "收藏", color: "#64748b", order: 0, kind: "normal" },
  { id: "stage-applied", name: "已申请", color: "#2563eb", order: 1, kind: "normal" },
  { id: "stage-assessment", name: "笔试/测评", color: "#7c3aed", order: 2, kind: "normal" },
  { id: "stage-interviewing", name: "面试中", color: "#d97706", order: 3, kind: "normal" },
  { id: "stage-offer", name: "已获 Offer", color: "#15803d", order: 4, kind: "offer" },
  { id: "stage-rejected", name: "已拒绝", color: "#b91c1c", order: 5, kind: "rejected" },
  { id: "stage-withdrawn", name: "已放弃", color: "#475569", order: 6, kind: "withdrawn" },
] as const satisfies readonly DefaultStageDefinition[];

export interface StageServiceDependencies {
  now?: () => string;
  createId?: () => string;
}

export interface CreateStageInput {
  name: string;
  color: string;
  order: number;
  kind?: StageKind;
}

export interface UpdateStageInput {
  name?: string;
  color?: string;
  order?: number;
}

export interface StageDeletePreview {
  id: string;
  name: string;
  kind: StageKind;
  applicationCount: number;
}

export interface StageDeleteOptions {
  confirmed?: boolean;
  replacementStageId?: string;
}

export class StageConfirmationRequired extends Error {
  constructor() {
    super("Stage deletion requires explicit confirmation.");
    this.name = "StageConfirmationRequired";
  }
}

export class StageReplacementRequired extends Error {
  readonly applicationCount: number;

  constructor(applicationCount: number) {
    super("A replacement stage is required for associated applications.");
    this.name = "StageReplacementRequired";
    this.applicationCount = applicationCount;
  }
}

function defaultNow(): string {
  return new Date().toISOString();
}

function defaultCreateId(): string {
  return crypto.randomUUID();
}

function isStageKind(value: unknown): value is StageKind {
  return typeof value === "string" && STAGE_KINDS.includes(value as StageKind);
}

function validateEditableValues(input: { name?: string; color?: string; order?: number }): void {
  if (input.name !== undefined && !input.name.trim()) {
    throw new Error("Stage name cannot be empty.");
  }
  if (input.color !== undefined && !input.color.trim()) {
    throw new Error("Stage color cannot be empty.");
  }
  if (input.order !== undefined && (!Number.isInteger(input.order) || input.order < 0)) {
    throw new Error("Stage order must be a non-negative integer.");
  }
}

export class StageService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
  readonly #createId: () => string;

  constructor(database: IDBDatabase, dependencies: StageServiceDependencies = {}) {
    this.#database = database;
    this.#now = dependencies.now ?? defaultNow;
    this.#createId = dependencies.createId ?? defaultCreateId;
  }

  async ensureDefaultStages(): Promise<Stage[]> {
    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "Stage.createdAt");
    await runTransaction(this.#database, STORE_NAMES.stages, "readwrite", async (transaction) => {
      const store = transaction.objectStore(STORE_NAMES.stages);
      for (const definition of DEFAULT_STAGES) {
        const existing = await requestToPromise<Stage | undefined>(store.get(definition.id));
        if (existing) {
          if (!isStageKind(existing.kind)) {
            throw new Error(`Invalid Stage.kind: ${existing.id}`);
          }
          continue;
        }
        const stage: Stage = {
          ...definition,
          id: definition.id,
          createdAt: timestamp,
          updatedAt: timestamp,
        };
        await requestToPromise(store.add(stage));
      }
    });
    return this.listStages();
  }

  initializeDefaults(): Promise<Stage[]> {
    return this.ensureDefaultStages();
  }

  getStage(stageId: string): Promise<Stage | undefined> {
    return runTransaction(this.#database, STORE_NAMES.stages, "readonly", (transaction) =>
      requestToPromise<Stage | undefined>(
        transaction.objectStore(STORE_NAMES.stages).get(stageId),
      ),
    );
  }

  get(stageId: string): Promise<Stage | undefined> {
    return this.getStage(stageId);
  }

  async listStages(): Promise<Stage[]> {
    const stages = await runTransaction(
      this.#database,
      STORE_NAMES.stages,
      "readonly",
      (transaction) =>
        requestToPromise<Stage[]>(transaction.objectStore(STORE_NAMES.stages).getAll()),
    );
    return stages.sort((left, right) => left.order - right.order || left.id.localeCompare(right.id));
  }

  list(): Promise<Stage[]> {
    return this.listStages();
  }

  async createStage(input: CreateStageInput): Promise<Stage> {
    validateEditableValues(input);
    const kind = input.kind ?? "normal";
    if (!isStageKind(kind)) throw new Error("Invalid Stage.kind");
    const timestamp = this.#now();
    assertAbsoluteIsoTimestamp(timestamp, "Stage.createdAt");
    const stage: Stage = {
      ...input,
      kind,
      id: this.#createId(),
      name: input.name.trim(),
      color: input.color.trim(),
      createdAt: timestamp,
      updatedAt: timestamp,
    };
    await runTransaction(this.#database, STORE_NAMES.stages, "readwrite", (transaction) =>
      requestToPromise(transaction.objectStore(STORE_NAMES.stages).add(stage)),
    );
    return stage;
  }

  create(input: CreateStageInput): Promise<Stage> {
    return this.createStage(input);
  }

  async updateStage(stageId: string, patch: UpdateStageInput): Promise<Stage> {
    if ("kind" in patch) {
      throw new Error("Stage.kind cannot be changed.");
    }
    validateEditableValues(patch);
    const candidate = this.#now();
    assertAbsoluteIsoTimestamp(candidate, "Stage.updatedAt");
    return runTransaction(this.#database, STORE_NAMES.stages, "readwrite", async (transaction) => {
      const store = transaction.objectStore(STORE_NAMES.stages);
      const existing = await requestToPromise<Stage | undefined>(store.get(stageId));
      if (!existing) throw new Error(`Stage not found: ${stageId}`);
      const updated: Stage = {
        ...existing,
        ...patch,
        ...(patch.name !== undefined ? { name: patch.name.trim() } : {}),
        ...(patch.color !== undefined ? { color: patch.color.trim() } : {}),
        id: existing.id,
        kind: existing.kind,
        createdAt: existing.createdAt,
        updatedAt: nextUpdatedTimestamp(candidate, existing.updatedAt),
      };
      await requestToPromise(store.put(updated));
      return updated;
    });
  }

  update(stageId: string, patch: UpdateStageInput): Promise<Stage> {
    return this.updateStage(stageId, patch);
  }

  renameStage(stageId: string, name: string): Promise<Stage> {
    return this.updateStage(stageId, { name });
  }

  setStageColor(stageId: string, color: string): Promise<Stage> {
    return this.updateStage(stageId, { color });
  }

  async reorderStages(stageIds: readonly string[]): Promise<Stage[]> {
    if (new Set(stageIds).size !== stageIds.length) {
      throw new Error("Stage order cannot contain duplicate ids.");
    }
    const candidate = this.#now();
    assertAbsoluteIsoTimestamp(candidate, "Stage.updatedAt");
    await runTransaction(this.#database, STORE_NAMES.stages, "readwrite", async (transaction) => {
      const store = transaction.objectStore(STORE_NAMES.stages);
      const existing = await requestToPromise<Stage[]>(store.getAll());
      const existingIds = new Set(existing.map(({ id }) => id));
      if (stageIds.length !== existing.length || stageIds.some((id) => !existingIds.has(id))) {
        throw new Error("Stage order must include every stage exactly once.");
      }
      const byId = new Map(existing.map((stage) => [stage.id, stage]));
      for (const [order, stageId] of stageIds.entries()) {
        const stage = byId.get(stageId)!;
        const updated: Stage = {
          ...stage,
          order,
          updatedAt: nextUpdatedTimestamp(candidate, stage.updatedAt),
        };
        await requestToPromise(store.put(updated));
      }
    });
    return this.listStages();
  }

  reorder(stageIds: readonly string[]): Promise<Stage[]> {
    return this.reorderStages(stageIds);
  }

  async previewDelete(stageId: string): Promise<StageDeletePreview> {
    return runTransaction(
      this.#database,
      [STORE_NAMES.stages, STORE_NAMES.applications],
      "readonly",
      async (transaction) => {
        const stage = await requestToPromise<Stage | undefined>(
          transaction.objectStore(STORE_NAMES.stages).get(stageId),
        );
        if (!stage) throw new Error(`Stage not found: ${stageId}`);
        const applicationCount = await requestToPromise(
          transaction
            .objectStore(STORE_NAMES.applications)
            .index("stageId")
            .count(stageId),
        );
        return { id: stage.id, name: stage.name, kind: stage.kind, applicationCount };
      },
    );
  }

  async deleteStage(stageId: string, options: StageDeleteOptions = {}): Promise<void> {
    if (!options.confirmed) throw new StageConfirmationRequired();
    const candidate = this.#now();
    assertAbsoluteIsoTimestamp(candidate, "Stage.deletedAt");
    await runTransaction(
      this.#database,
      [STORE_NAMES.stages, STORE_NAMES.applications, STORE_NAMES.applicationTimelineEvents],
      "readwrite",
      async (transaction) => {
        const stageStore = transaction.objectStore(STORE_NAMES.stages);
        const stage = await requestToPromise<Stage | undefined>(stageStore.get(stageId));
        if (!stage) throw new Error(`Stage not found: ${stageId}`);
        if (stage.kind !== "normal") {
          throw new Error("A result stage cannot be deleted.");
        }

import type { ResumeIngestionService } from "../features/resumes/ingestion";
import type { ResumeLibraryService } from "../features/resumes/resumeLibrary";

export interface CreateAppOptions {
  resumeLibrary?: ResumeLibraryService;
  resumeIngestion?: ResumeIngestionService;
}

export function createApp(
  documentRef: Document,
  options: CreateAppOptions = {},
): HTMLElement {
  const root = documentRef.getElementById("app");

  if (!root) {
    throw new Error("找不到应用挂载节点 #app");
  }

  root.innerHTML = `
    <div class="app-shell">
      <header class="topbar">
        <div class="brand" aria-label="求职工作台">
          <span class="brand-mark" aria-hidden="true">职</span>
          <span>求职工作台</span>
        </div>
        <div class="local-status" role="status" aria-live="polite">
          <span class="status-dot" aria-hidden="true"></span>
          本地数据已就绪
        </div>
      </header>

      <main>
        <section class="overview" aria-labelledby="page-title">
          <p class="section-label">概览</p>
          <div class="overview-heading">
            <h1 id="page-title">求职工作台</h1>
            <p>数据仅保存在此浏览器</p>
          </div>

          <dl class="summary-grid" aria-label="本地资料概览">
            <div class="summary-item">
              <dt>简历</dt>
              <dd class="resume-summary-count">0 份简历</dd>
            </div>
            <div class="summary-item">
              <dt>职位</dt>
              <dd>0 个职位</dd>
            </div>
            <div class="summary-item summary-item--accent">
              <dt>近期面试</dt>
              <dd>暂无安排</dd>
            </div>
          </dl>
        </section>

        <section class="resume-library" aria-labelledby="resume-library-title">
          <div class="section-heading">
            <div>
              <p class="section-label">资料</p>
              <h2 id="resume-library-title">简历版本库</h2>
            </div>
            <label class="resume-upload-button">
              <span>上传简历</span>
              <input class="resume-file-input" type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" />
            </label>
          </div>
          <div class="resume-library-toolbar">
            <label for="resume-search">搜索简历</label>
            <input id="resume-search" type="search" placeholder="按名称、文件名或标签搜索" autocomplete="off" />
            <button type="button" class="resume-refresh" aria-label="刷新简历列表">刷新</button>
          </div>
          <div class="resume-library-status" role="status" aria-live="polite" aria-atomic="true">暂无简历版本</div>
          <div class="resume-library-list" aria-live="polite"></div>
          <div class="resume-editor" hidden>
            <label for="resume-text-editor">确认简历文本</label>
            <textarea id="resume-text-editor" rows="12"></textarea>
            <div class="resume-editor__actions">
              <button type="button" data-action="confirm-text">确认文本</button>
              <button type="button" data-action="cancel-text">取消</button>
            </div>
          </div>
          <div class="resume-metadata-editor" hidden>
            <h3>编辑版本信息</h3>
            <label for="resume-name-editor">版本名称</label>
            <input id="resume-name-editor" type="text" />
            <label for="resume-tags-editor">标签（用逗号分隔）</label>
            <input id="resume-tags-editor" type="text" />
            <div class="resume-editor__actions">
              <button type="button" data-action="save-metadata">保存</button>
              <button type="button" data-action="cancel-metadata">取消</button>
            </div>
          </div>
          <div class="resume-delete-preview" role="dialog" aria-modal="true" aria-labelledby="resume-delete-title" hidden>
            <h3 id="resume-delete-title">确认删除简历</h3>
            <p class="resume-delete-summary"></p>
            <div class="resume-editor__actions">
              <button type="button" data-action="confirm-delete">确认删除</button>
              <button type="button" data-action="cancel-delete">取消</button>
            </div>
          </div>
        </section>

        <section class="today" aria-labelledby="today-title">
          <div class="section-heading">
            <div>
              <p class="section-label">今天</p>
              <h2 id="today-title">待处理事项</h2>
            </div>
            <span class="count" aria-label="0 项">0</span>
          </div>
          <div class="empty-state">
            <span class="empty-line" aria-hidden="true"></span>
            <p>今天没有待处理事项</p>
          </div>
        </section>
      </main>
    </div>
  `;

  const status = root.querySelector<HTMLElement>(".resume-library-status");
  const resumeSummary = root.querySelector<HTMLElement>(".resume-summary-count");
  const list = root.querySelector<HTMLElement>(".resume-library-list");
  const search = root.querySelector<HTMLInputElement>("#resume-search");
  const fileInput = root.querySelector<HTMLInputElement>(".resume-file-input");
  const refresh = root.querySelector<HTMLButtonElement>(".resume-refresh");
  const editor = root.querySelector<HTMLElement>(".resume-editor");
  const editorText = root.querySelector<HTMLTextAreaElement>("#resume-text-editor");
  const metadataEditor = root.querySelector<HTMLElement>(".resume-metadata-editor");
  const nameEditor = root.querySelector<HTMLInputElement>("#resume-name-editor");
  const tagsEditor = root.querySelector<HTMLInputElement>("#resume-tags-editor");
  const deletePreview = root.querySelector<HTMLElement>(".resume-delete-preview");
  const deleteSummary = root.querySelector<HTMLElement>(".resume-delete-summary");
  let editingResumeId: string | undefined;
  let metadataResumeId: string | undefined;
  let pendingDeleteId: string | undefined;

  const render = async (query = "") => {
    if (!list) return;
    const resumes = options.resumeLibrary ? await options.resumeLibrary.search(query) : [];
    list.innerHTML = resumes.length
      ? resumes.map((resume) => `
          <article class="resume-library-item" data-resume-id="${resume.id}">
            <div class="resume-library-item__body">
              <h3 title="${escapeHtml(resume.name)}">${escapeHtml(resume.name)}</h3>
              <p>${escapeHtml(resume.fileName)}</p>
              <p class="resume-library-item__meta">${escapeHtml(resume.status)}${resume.tags.length ? ` · ${escapeHtml(resume.tags.join("、"))}` : ""}</p>
            </div>
            <div class="resume-library-item__actions">
              <button type="button" data-action="preview" data-resume-id="${resume.id}">预览文本</button>
              <button type="button" data-action="edit-metadata" data-resume-id="${resume.id}">编辑名称和标签</button>
              ${resume.status === "extraction-failed" ? `<button type="button" data-action="retry" data-resume-id="${resume.id}">重试提取</button>` : ""}
              <button type="button" data-action="export" data-resume-id="${resume.id}">导出文本</button>
              <button type="button" data-action="download" data-resume-id="${resume.id}">下载原文件</button>
              <button type="button" data-action="delete" data-resume-id="${resume.id}">删除</button>
            </div>
          </article>
        `).join("")
      : "";
    if (status) status.textContent = resumes.length ? `${resumes.length} 个简历版本` : "暂无简历版本";
    if (resumeSummary) resumeSummary.textContent = `${resumes.length} 份简历`;
  };

  search?.addEventListener("input", () => void render(search.value));
  refresh?.addEventListener("click", () => void render(search?.value ?? ""));
  fileInput?.addEventListener("change", async () => {
    const file = fileInput.files?.[0];
    if (!file || !options.resumeIngestion) return;
    try {
      const result = await options.resumeIngestion.ingest(file);
      if (status) status.textContent = result.outcome === "needs-review" ? "提取完成，请确认文本" : "提取失败，请粘贴或校正文本";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "简历保存失败";
    }
    fileInput.value = "";
  });

  list?.addEventListener("click", async (event) => {
    const target = event.target as HTMLElement;
    const button = target.closest<HTMLButtonElement>("button[data-action]");
    const resumeId = button?.dataset.resumeId;
    if (!button || !resumeId || !options.resumeLibrary) return;
    try {
      if (button.dataset.action === "preview") {
        const textRecord = await options.resumeLibrary.getResumeText(resumeId, "confirmed")
          ?? await options.resumeLibrary.getResumeText(resumeId, "extracted")
          ?? await options.resumeLibrary.getResumeText(resumeId, "manual");
        editingResumeId = resumeId;
        if (editorText) editorText.value = textRecord?.text ?? "";
        if (editor) editor.hidden = false;
        if (status) status.textContent = textRecord ? `已读取文本（${textRecord.text.length} 字）` : "尚未提取文本，请粘贴或校正";
      } else if (button.dataset.action === "download") {
        const download = await options.resumeLibrary.getDownloadData(resumeId);
        triggerDownload(documentRef, download.blob, download.fileName);
        if (status) status.textContent = "原文件已下载";
      } else if (button.dataset.action === "export") {
        const blob = await options.resumeLibrary.exportConfirmedText(resumeId);
        triggerDownload(documentRef, blob, "resume-confirmed.txt");
        if (status) status.textContent = "确认文本已导出";
      } else if (button.dataset.action === "edit-metadata") {
        const resume = await options.resumeLibrary.getResume(resumeId);
        if (!resume) throw new Error("简历版本不存在");
        metadataResumeId = resumeId;
        if (nameEditor) nameEditor.value = resume.name;
        if (tagsEditor) tagsEditor.value = resume.tags.join(", ");
        if (metadataEditor) metadataEditor.hidden = false;
      } else if (button.dataset.action === "retry") {
        if (!options.resumeIngestion) throw new Error("当前无法重试文本提取");
        const result = await options.resumeIngestion.retryExtraction(resumeId);
        if (status) status.textContent = result.outcome === "needs-review" ? "重新提取完成，请确认文本" : "提取仍然失败，可继续手动粘贴文本";
        await render(search?.value ?? "");
      } else if (button.dataset.action === "delete") {
        const preview = await options.resumeLibrary.previewDelete(resumeId);
        pendingDeleteId = resumeId;
        if (deleteSummary) deleteSummary.textContent = `将删除“${preview.name}”及其原文件；已固化的使用历史不会删除。`;
        if (deletePreview) deletePreview.hidden = false;
        if (status) status.textContent = "删除预览已打开，尚未删除任何数据";
      }
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "操作失败";
    }
  });

  metadataEditor?.addEventListener("click", async (event) => {
    const action = (event.target as HTMLElement).closest<HTMLButtonElement>("button[data-action]")?.dataset.action;
    if (action === "cancel-metadata") {
      metadataEditor.hidden = true;
      metadataResumeId = undefined;
      return;
    }
    if (action !== "save-metadata" || !metadataResumeId || !options.resumeLibrary) return;
    try {
      await options.resumeLibrary.updateMetadata(metadataResumeId, {
        name: nameEditor?.value,
        tags: tagsEditor?.value.split(/[,，]/),
      });
      metadataEditor.hidden = true;
      if (status) status.textContent = "版本名称和标签已保存";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "版本信息保存失败";
    }
  });

  deletePreview?.addEventListener("click", async (event) => {
    const action = (event.target as HTMLElement).closest<HTMLButtonElement>("button[data-action]")?.dataset.action;
    if (action === "cancel-delete") {
      deletePreview.hidden = true;
      pendingDeleteId = undefined;
      if (status) status.textContent = "已取消删除，数据未改变";
      return;
    }
    if (action !== "confirm-delete" || !pendingDeleteId || !options.resumeLibrary) return;
    try {
      await options.resumeLibrary.deleteResume(pendingDeleteId, { confirmed: true });
      deletePreview.hidden = true;
      pendingDeleteId = undefined;
      if (status) status.textContent = "简历已删除";
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "删除失败";
    }
  });

  editor?.addEventListener("click", async (event) => {
    const target = event.target as HTMLElement;
    const action = target.closest<HTMLButtonElement>("button[data-action]")?.dataset.action;
    if (action === "cancel-text") {
      editor.hidden = true;
      editingResumeId = undefined;
      return;
    }
    if (action !== "confirm-text" || !editingResumeId || !options.resumeLibrary || !editorText) return;
    try {
      await options.resumeLibrary.confirmText(editingResumeId, editorText.value);
      if (status) status.textContent = "文本已保存并确认";
      editor.hidden = true;
      await render(search?.value ?? "");
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : "文本保存失败";
    }
  });

  void render();

  return root;
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "'": "&#39;",
    '"': "&quot;",
  })[character] ?? character);
}

function triggerDownload(documentRef: Document, blob: Blob, fileName: string): void {
  if (typeof URL.createObjectURL !== "function") return;
  const anchor = documentRef.createElement("a");
  anchor.href = URL.createObjectURL(blob);
  anchor.download = fileName;
  anchor.hidden = true;
  documentRef.body.append(anchor);
  anchor.click();
  anchor.remove();
  URL.revokeObjectURL(anchor.href);
}

